import { readFileSync, writeFileSync, existsSync } from "fs";
import { join } from "path";
import pLimit from "p-limit";
import { client } from "./_lib/client.mjs";

// ─── Edit before running ──────────────────────────────────────────────
//
// LOCAL_DIR holds the image files. METADATA_FILE describes each image
// (typically generated by `generate-local-metadata.mjs`):
//
// [
//   {
//     "filename": "_DSC1234.jpg",
//     "title": "Short title",
//     "altText": "Detailed description for screen readers",
//     "caption": "Brief caption",
//     "category": "photography",      // matches a key in CATEGORY_IDS below
//     "tags": ["Architecture"],       // matches keys in TAG_IDS below
//     "date": "2024-08-15",           // optional, YYYY-MM-DD
//     "gps": { "lat": 0, "lng": 0 }   // optional
//   }
//   // …
// ]
//
// CATEGORY_IDS and TAG_IDS map the strings in your metadata.json to the
// _id of the matching `category` / `tag` document in Sanity. Replace
// these with your own — query them via the client or look them up in
// Studio. If a tag isn't in this map it's silently dropped.

const LOCAL_DIR = process.env.HOME + "/Desktop/export";
const METADATA_FILE = join(LOCAL_DIR, "metadata.json");
const PROGRESS_FILE = join(LOCAL_DIR, "upload-progress.json");

// Replace these with your own Sanity document IDs.
const CATEGORY_IDS = {
  // photography: "REPLACE_WITH_CATEGORY_DOC_ID",
  // design: "REPLACE_WITH_CATEGORY_DOC_ID",
  // music: "REPLACE_WITH_CATEGORY_DOC_ID",
};

// Replace these with your own Sanity document IDs.
const TAG_IDS = {
  // Architecture: "REPLACE_WITH_TAG_DOC_ID",
  // Concert: "REPLACE_WITH_TAG_DOC_ID",
  // Installation: "REPLACE_WITH_TAG_DOC_ID",
  // Landscape: "REPLACE_WITH_TAG_DOC_ID",
  // "Product Design": "REPLACE_WITH_TAG_DOC_ID",
  // Typography: "REPLACE_WITH_TAG_DOC_ID",
  // Branding: "REPLACE_WITH_TAG_DOC_ID",
  // Website: "REPLACE_WITH_TAG_DOC_ID",
};

// ──────────────────────────────────────────────────────────────────────

// Sanity defaults `lqip` + `palette`; explicit `location` + `exif` pick up
// GPS and camera metadata from the JPEG header at upload time.
const EXTRACT = ["lqip", "palette", "location", "exif"];

const limit = pLimit(5);

function makePortableText(text) {
  return [
    {
      _type: "block",
      _key: crypto.randomUUID().slice(0, 12),
      style: "normal",
      markDefs: [],
      children: [
        {
          _type: "span",
          _key: crypto.randomUUID().slice(0, 12),
          marks: [],
          text,
        },
      ],
    },
  ];
}

async function run() {
  if (Object.keys(CATEGORY_IDS).length === 0) {
    console.error(
      "CATEGORY_IDS is empty — open upload-metadata.mjs and replace the placeholders before running."
    );
    process.exit(1);
  }

  const metadata = JSON.parse(readFileSync(METADATA_FILE, "utf8"));

  // Load progress for resume
  let uploaded = new Set();
  if (existsSync(PROGRESS_FILE)) {
    try {
      const content = readFileSync(PROGRESS_FILE, "utf8").trim();
      if (content) uploaded = new Set(JSON.parse(content));
    } catch {
      uploaded = new Set();
    }
  }

  const todo = metadata.filter((m) => !uploaded.has(m.filename));
  console.log(
    `\n=== Upload: ${metadata.length} total, ${uploaded.size} done, ${todo.length} remaining ===\n`
  );

  let success = 0;
  let failed = 0;

  const fallbackCatKey = Object.keys(CATEGORY_IDS)[0];

  const tasks = todo.map((entry) =>
    limit(async () => {
      const filePath = join(LOCAL_DIR, entry.filename);

      try {
        const imageBuffer = readFileSync(filePath);

        // Upload asset
        const asset = await client.assets.upload("image", imageBuffer, {
          filename: entry.filename,
          extract: EXTRACT,
        });

        // Build categories array
        const catSlug = entry.category && CATEGORY_IDS[entry.category]
          ? entry.category
          : fallbackCatKey;
        const catId = CATEGORY_IDS[catSlug];
        const categories = [{ _type: "reference", _ref: catId, _key: catSlug }];

        // Build tags array
        const tags = [];
        for (const tagName of entry.tags || []) {
          const tagId = TAG_IDS[tagName];
          if (tagId) {
            tags.push({
              _type: "reference",
              _ref: tagId,
              _key: tagName.toLowerCase().replace(/\s+/g, "-"),
            });
          }
        }

        const caption = makePortableText(entry.caption || entry.title);

        // Build document
        const doc = {
          _type: "media",
          title: entry.title,
          mediaType: "image",
          altText: entry.altText,
          caption,
          image: {
            _type: "image",
            asset: { _type: "reference", _ref: asset._id },
          },
          categories,
          featured: false,
          hidden: false,
        };

        if (tags.length > 0) doc.tags = tags;

        // Add location if GPS available
        if (entry.gps && entry.gps.lat && entry.gps.lng) {
          doc.location = {
            _type: "geopoint",
            lat: entry.gps.lat,
            lng: entry.gps.lng,
          };
        }

        // Add date
        if (entry.date) doc.date = entry.date;

        await client.create(doc);
        uploaded.add(entry.filename);
        success++;

        // Save progress every 10 successes. With 5-way concurrency the
        // counter can tick past 10/20/... from multiple tasks in a burst,
        // producing a few extra writes — harmless (same content) and the
        // final write below guarantees completeness.
        if (success % 10 === 0) {
          writeFileSync(PROGRESS_FILE, JSON.stringify([...uploaded]));
        }

        const total = uploaded.size;
        const pct = ((total / metadata.length) * 100).toFixed(0);
        console.log(
          `  [${total}/${metadata.length}] (${pct}%) ${entry.filename.slice(0, 25)}… → "${entry.title}"`
        );
      } catch (err) {
        failed++;
        console.error(`  FAIL ${entry.filename.slice(0, 25)}…: ${err.message.slice(0, 80)}`);
      }
    })
  );

  await Promise.all(tasks);

  // Final save
  writeFileSync(PROGRESS_FILE, JSON.stringify([...uploaded]));
  console.log(
    `\n=== Done. Success: ${success}, Failed: ${failed}, Total uploaded: ${uploaded.size} ===\n`
  );
}

run();
